    def _match_custom_tag_block(
        self, element: marko.element.Element
    ) -> Optional[tuple[str, str]]:
        """Detect a paragraph that wraps a single custom tag (signature/stamp).

        Returns a ``(class_name, text)`` tuple when ``element`` is a paragraph of
        the form ``<signature>TEXT</signature>`` or ``<stamp>TEXT</stamp>``, else
        ``None``. ``text`` is the (possibly empty) content between the tags.
        """
        if not isinstance(element, marko.block.Paragraph):
            return None
        children = getattr(element, "children", None)
        if not isinstance(children, list) or len(children) < 2:
            return None

        first, last = children[0], children[-1]
        if not isinstance(first, marko.inline.InlineHTML) or not isinstance(
            last, marko.inline.InlineHTML
        ):
            return None

        open_str = first.children if isinstance(first.children, str) else ""
        close_str = last.children if isinstance(last.children, str) else ""

        open_match = re.match(
            r"\s*<\s*([A-Za-z][\w-]*)\b[^>]*>\s*$", open_str, flags=re.IGNORECASE
        )
        if open_match is None:
            return None
        tag = open_match.group(1).lower()
        if tag not in self._CUSTOM_TAGS:
            return None

        if re.match(rf"\s*</\s*{tag}\s*>\s*$", close_str, flags=re.IGNORECASE) is None:
            return None

        inner = "".join(
            self._collect_inline_text(child) for child in children[1:-1]
        )
        return self._CUSTOM_TAGS[tag], unescape(inner).strip()

